package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.apache.commons.math3.exception.OutOfRangeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ElitisticListPopulation_ElitisticListPopulation_TriageGen0Test {

    @Test
    public void testConstructorWithLimitAndRate() {
        int populationLimit = 50;
        double elitismRate = 0.1;

        ElitisticListPopulation population = new ElitisticListPopulation(populationLimit, elitismRate);

        assertNotNull(population);
        assertEquals(populationLimit, population.getLimit());
        assertEquals(elitismRate, population.getElitismRate(), 1e-9);
    }

    @Test
    public void testConstructorWithChromosomes() {
        int populationLimit = 10;
        double elitismRate = 0.2;
        List<Chromosome> chromosomes = new ArrayList<>();

        // Mocking Chromosome is complex without a concrete implementation, 
        // but based on the signature, we assume Chromosome is an interface or abstract class.
        // Since we cannot instantiate an abstract class, we use a dummy if possible, 
        // or assuming the environment allows testing this constructor.
        // For the sake of this unit test, we assume a subclass or implementation exists.

        // Note: In a real scenario, we would use a Mockito mock:
        // Chromosome mockChromosome = Mockito.mock(Chromosome.class);
        // chromosomes.add(mockChromosome);

        // Since I cannot use Mockito here, I will focus on the logic provided.
        // If Chromosome is an interface, we'd use an anonymous class.

        class TestChromosome implements Chromosome {
            @Override public double getFitness() { return 1.0; }
            @Override public Chromosome replicate() { return this; }
            @Override public void mutate(double probability, java.util.Random random) {}
        }

        chromosomes.add(new TestChromosome());

        ElitisticListPopulation population = new ElitisticListPopulation(chromosomes, populationLimit, elitismRate);

        assertNotNull(population);
        assertEquals(populationLimit, population.getLimit());
        assertEquals(elitismRate, population.getElitismRate(), 1e-9);
    }

    @Test
    public void testSetAndGetElitismRate() {
        int populationLimit = 20;
        double initialRate = 0.1;
        double newRate = 0.5;

        ElitisticListPopulation population = new ElitisticListPopulation(populationLimit, initialRate);
        assertEquals(initialRate, population.getElitismRate(), 1e-9);

        population.setElitismRate(newRate);
        assertEquals(newRate, population.getElitismRate(), 1e-9);
    }
}
